<script setup>
import {ref,watch,onUnmounted} from 'vue';
import {state,api,scope,can,ask,notify,useResource,allowedApi} from '../lib/workspace';
import {date} from '../lib/format';
import BaseModal from '../components/BaseModal.vue';
import DateInput from '../components/DateInput.vue';
import AuditEvidence from '../components/AuditEvidence.vue';
const {data:catalogs,reload,error:loadError}=useResource(()=>allowedApi('auditor.catalogs',scope('/auditor/catalogs')));
const selected=ref(null),rows=ref({rows:[],total:0}),search=ref(''),status=ref(''),kind=ref('parameters'),page=ref(1),busy=ref(false),error=ref(''),form=ref(null),entry=ref(null),entryIndex=ref(null),preview=ref(null),comparison=ref(null),compareId=ref('');
watch(()=>[state.companyId,state.period.slice(0,4)],()=>{selected.value=null;rows.value={rows:[],total:0};error.value='';comparison.value=null});
onUnmounted(()=>{if(form.value||entry.value)state.editor=null});
async function run(fn){if(busy.value)return;busy.value=true;error.value='';const guard={token:Symbol(),name:'Catálogo em processamento'};if(!state.editor)state.editor=guard;try{await fn()}catch(e){error.value=e.message}finally{busy.value=false;if(state.editor?.token===guard.token)state.editor=null}}
async function browse(){if(!selected.value)return;rows.value=await api(scope(`/auditor/catalogs/${selected.value.id}/entries?search=${encodeURIComponent(search.value)}&status=${status.value}&page=${page.value}&kind=${kind.value}`))}
async function select(c){await run(async()=>{selected.value=await api(scope(`/auditor/catalogs/${c.id}`));page.value=1;comparison.value=null;await browse()})}
function blank(){return {ncm:'',ex_code:'',description:'',cst:'',cclass_trib:'',reduction_type:'',legal_reference_raw:''}}
function newCatalog(reference=false,revision=null){preview.value=null;form.value={reference,revision,name:revision?revision.name+' — revisão':reference?'Referência histórica Auditor 1.2.2':'',source:'',valid_from:state.period.slice(0,4)+'-01-01',valid_to:state.period.slice(0,4)+'-12-31',entries:[blank()],reviewed:false};state.editor={name:'Catálogo do Auditor'}}
function edit(r=null){entry.value=r?{...r}:blank();entryIndex.value=r?._index??null;state.editor={name:'Regra do catálogo'}}
async function close(){if(await ask({title:'Fechar edição?',message:'Descartar os dados ainda não salvos?',confirmLabel:'Descartar'})){form.value=null;entry.value=null;state.editor=null}}
async function save(){await run(async()=>{const f=form.value;const path=f.reference?'/auditor/catalogs/reference':f.revision?`/auditor/catalogs/${f.revision.id}/revision`:'/auditor/catalogs';const result=await api(scope(path),{method:'POST',body:{...f,acknowledge_issues:f.reviewed}});form.value=null;state.editor=null;selected.value=await api(scope(`/auditor/catalogs/${result.id}`));await reload();await browse();notify('Rascunho salvo. Revise os diagnósticos antes de publicar.')})}
async function saveEntry(){await run(async()=>{const id=selected.value.id;await api(scope(`/auditor/catalogs/${id}/entries`+(entryIndex.value===null?'':'/'+entryIndex.value)),{method:entryIndex.value===null?'POST':'PUT',body:{version:selected.value.version,entry:entry.value}});entry.value=null;state.editor=null;selected.value=await api(scope(`/auditor/catalogs/${id}`));await browse();await reload()})}
async function remove(r){const reason=await ask({title:'Remover regra do rascunho?',message:'A exclusão será registrada; versões publicadas permanecem intactas.'});if(!reason)return;await run(async()=>{await api(scope(`/auditor/catalogs/${selected.value.id}/entries/${r._index}`),{method:'DELETE',body:{version:selected.value.version}});selected.value=await api(scope(`/auditor/catalogs/${selected.value.id}`));await browse();await reload()})}
async function publish(){const c=selected.value;const reason=await ask({title:'Publicar versão revisada?',message:'Confirme a fonte, a vigência e a análise das regras. A publicação torna a versão imutável.',inputLabel:'Conclusão da revisão',required:true});if(!reason)return;await run(async()=>{await api(scope(`/auditor/catalogs/${c.id}/publish`),{method:'POST',body:{version:c.version,reason}});selected.value=await api(scope(`/auditor/catalogs/${c.id}`));await reload()})}
async function importXlsx(e){const f=e.target.files[0];if(!f)return;await run(async()=>{if(f.size>20*1024*1024)throw Error('Limite de 20 MiB.');const content=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result.split(',')[1]);r.onerror=reject;r.readAsDataURL(f)});preview.value=await api(scope('/auditor/catalogs/import-preview'),{method:'POST',body:{filename:f.name,content_base64:content}});form.value.entries=preview.value.entries;form.value.source_id=preview.value.source_id;form.value.reviewed=false})}
async function compare(){await run(async()=>{comparison.value=await api(scope(`/auditor/catalogs/${compareId.value}/compare/${selected.value.id}`))})}
</script>
<template><div>
<p v-if="error||loadError" class="message error" role="alert">{{error||loadError}}</p>
<section class="panel"><div class="panel-heading"><h2>Catálogos e versões</h2><div class="actions"><button v-if="can('auditor.catalogs','create')" class="button primary" @click="newCatalog()">Novo catálogo</button><button v-if="can('auditor.catalogs','create')&&can('auditor.catalogs','import')" class="button outline" @click="newCatalog(true)">Importar referência 1.2.2</button></div></div>
<div class="table-scroll"><table><thead><tr><th>Versão</th><th>Fonte / vigência</th><th>Situação</th><th></th></tr></thead><tbody><tr v-for="c in catalogs" :key="c.id"><td>{{c.name}}<br><code>{{c.sha256.slice(0,16)}}</code></td><td>{{c.source}}<br>{{date(c.valid_from)}} a {{date(c.valid_to)}}</td><td>{{c.state==='draft'?'Rascunho':'Publicado'}} · {{c.entry_count}} linhas</td><td><button class="text-button" @click="select(c)">Consultar regras</button></td></tr></tbody></table></div></section>
<section v-if="selected" class="panel"><div class="panel-heading"><h2>{{selected.name}}</h2><div class="actions"><button v-if="can('auditor.catalogs','create')" class="button outline" @click="newCatalog(false,selected)">Nova revisão</button><button v-if="selected.state==='draft'&&can('auditor.catalogs','book')" class="button primary" :disabled="busy||selected.error_count>0" @click="publish">Publicar após revisão</button></div></div><div class="panel-body">
<p v-if="selected.reference?.notice" class="message warning">{{selected.reference.notice}}</p><p>{{selected.entry_count}} linhas · {{selected.item_count}} NCMs completos · {{selected.error_count}} erros impeditivos · versão de edição {{selected.version}}</p>
<details v-if="selected.issues?.length"><summary>Diagnósticos ({{selected.issues.length}})</summary><p v-for="(i,n) in selected.issues" :key="n">Linha {{i.source_row}} · {{i.ncm}} / {{i.ex_code||'—'}} · {{i.code}}: {{i.message}}</p></details>
<div class="form-grid"><label>Tabela<select v-model="kind" @change="page=1;run(browse)"><option value="parameters">NCM × classificação</option><option value="cst">Referência de CST</option><option value="cclass">Referência de cClassTrib</option></select></label><label>Pesquisar NCM, descrição ou código<input v-model="search" @keydown.enter.prevent="page=1;run(browse)"/></label><label>Situação<select v-model="status" @change="page=1;run(browse)"><option value="">Todas</option><option value="error">Erros impeditivos</option><option value="warning">Advertências</option><option value="valid">Válidas estruturalmente</option></select></label></div>
<div class="actions"><button class="button outline" @click="page=1;run(browse)">Pesquisar regras</button><button v-if="kind==='parameters'&&selected.state==='draft'&&can('auditor.catalogs','edit')" class="button primary" @click="edit()">Incluir regra</button><a v-if="selected.source_id&&can('auditor.catalogs','export')" :href="`/api${scope(`/auditor/catalogs/${selected.id}/original`)}`">Planilha original</a></div>
<div class="table-scroll"><table><thead><tr><th>NCM / EX</th><th>Descrição</th><th>CST / cClassTrib</th><th>Situação / origem</th><th>Ações</th></tr></thead><tbody><tr v-for="r in rows.rows" :key="r._index"><td>{{r.ncm||'—'}} / {{r.ex_code||'—'}}</td><td>{{r.description||r.name}}<details><summary>Condições e fonte</summary><AuditEvidence :value="r"/></details></td><td>{{r.cst||'—'}} / {{r.cclass_trib||'—'}}</td><td>{{r._status}} · linha {{r.source_row||'manual'}}</td><td><template v-if="kind==='parameters'&&selected.state==='draft'&&can('auditor.catalogs','edit')"><button class="text-button" @click="edit(r)">Editar regra</button><button class="text-button" @click="remove(r)">Excluir regra</button></template></td></tr></tbody></table></div>
<div class="actions"><button class="button" :disabled="busy||page===1" @click="page--;run(browse)">Anterior</button><span>Página {{page}} · {{rows.total}} resultados</span><button class="button" :disabled="busy||page*50>=rows.total" @click="page++;run(browse)">Próxima</button></div>
<div class="form-grid"><label>Comparar com a versão<select v-model="compareId"><option value="">Selecione</option><option v-for="c in catalogs.filter(c=>c.id!==selected.id)" :value="c.id">{{c.name}}</option></select></label><button class="button outline" :disabled="!compareId||busy" @click="compare">Comparar versões</button></div><details v-if="comparison" open><summary>{{comparison.total}} diferenças</summary><AuditEvidence :value="comparison.changes"/></details>
</div></section>
<BaseModal v-if="form" title="Catálogo do Auditor" wide @close="close"><form id="catalog-header" @submit.prevent="save"><div class="form-grid"><label>Nome da versão<input v-model="form.name" required autofocus/></label><label v-if="!form.reference&&!form.revision">Fonte e edição<input v-model="form.source" required/></label><label>Vigência inicial<DateInput v-model="form.valid_from" required/></label><label>Vigência final<DateInput v-model="form.valid_to" required/></label></div>
<p v-if="form.reference">Os registros históricos e seus diagnósticos serão copiados para um rascunho desta empresa. Nenhuma regra será publicada automaticamente.</p>
<template v-if="!form.reference&&!form.revision"><label v-if="can('auditor.catalogs','import')">Importar planilha XLSX<input type="file" accept=".xlsx" @change="importXlsx"/></label><div v-if="preview"><p>{{preview.rows}} linhas · {{preview.eligible}} elegíveis · {{preview.excluded}} excluídas</p><AuditEvidence :value="preview.issues"/><label class="check-label"><input type="checkbox" v-model="form.reviewed"/>Revisei os diagnósticos e exclusões.</label></div><div v-else class="form-grid"><label>NCM<input v-model="form.entries[0].ncm" required maxlength="8"/></label><label>EX<input v-model="form.entries[0].ex_code" maxlength="3"/></label><label>Descrição<input v-model="form.entries[0].description" required/></label><label>CST<input v-model="form.entries[0].cst" required maxlength="3"/></label><label>cClassTrib<input v-model="form.entries[0].cclass_trib" required maxlength="6"/></label></div></template><p v-if="error" class="message error">{{error}}</p></form><template #footer><button class="button" @click="close">Fechar</button><button class="button primary" type="submit" form="catalog-header" :disabled="busy">Salvar rascunho</button></template></BaseModal>
<BaseModal v-if="entry" title="Regra NCM / EX" wide @close="close"><form id="catalog-entry" @submit.prevent="saveEntry"><p v-if="entry.ncm_level==='hierarchy'">Agrupamento do catálogo. Não será usado como regra de NCM de produto.</p><div class="form-grid"><label>NCM<input v-model="entry.ncm" required :pattern="entry.ncm_level==='hierarchy'?'[0-9]{2,7}':'[0-9]{8}'" maxlength="8" autofocus/></label><label>EX<input v-model="entry.ex_code" maxlength="3"/></label><label>Descrição<input v-model="entry.description" required/></label><label>CST<input v-model="entry.cst" list="audit-csts" required pattern="[0-9]{3}"/></label><label>cClassTrib<input v-model="entry.cclass_trib" list="audit-classes" required pattern="[0-9]{6}"/></label><label>Redução / condição<input v-model="entry.reduction_type"/></label><label>Referência normativa<input v-model="entry.legal_reference_raw"/></label></div><datalist id="audit-csts"><option v-for="c in selected.reference?.cst" :value="c.cst">{{c.description}}</option></datalist><datalist id="audit-classes"><option v-for="c in selected.reference?.cclass" :value="c.cclass_trib">{{c.name}}</option></datalist><p v-if="error" class="message error">{{error}}</p></form><template #footer><button class="button" @click="close">Fechar</button><button class="button primary" type="submit" form="catalog-entry" :disabled="busy">Salvar regra</button></template></BaseModal>
</div></template>
<style scoped>.panel{margin-bottom:16px}.panel-body{padding:18px}.actions{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0;align-items:center}td{vertical-align:top}details{margin:8px 0}code{overflow-wrap:anywhere}</style>
